        "code": "class OptimizedThreatGraph:\n    def __init__(self):\n        self.adj = {}\n        self.memo = {}\n\n    def add_edge(self, u, v, cost):\n        if u not in self.adj:\n            self.adj[u] = []\n        self.adj[u].append((v, cost))\n\n    def find_shortest_attack_path(self, current, target, visited=None):\n        if visited is None:\n            visited = set()\n        state_key = (current, tuple(sorted(visited)))\n        if state_key in self.memo:\n            return self.memo[state_key]\n        if current == target:\n            return (0.0, [target])\n        if current in visited:\n            return (float(\"inf\"), [])\n\n        visited.add(current)\n        min_cost = float(\"inf\")\n        best_path = []\n\n        for nxt, weight in self.adj.get(current, []):\n            sub_cost, sub_path = self.find_shortest_attack_path(nxt, target, visited.copy())\n            total = weight + sub_cost\n            if total < min_cost:\n                min_cost = total\n                best_path = [current] + sub_path\n\n        self.memo[state_key] = (min_cost, best_path)\n        return self.memo[state_key]\n\ntg = OptimizedThreatGraph()\ntg.add_edge(\"Internet\", \"DMZ_Web\", 2.0)\ntg.add_edge(\"DMZ_Web\", \"Internal_API\", 5.0)\ntg.add_edge(\"DMZ_Web\", \"Bastion_Host\", 8.0)\ntg.add_edge(\"Bastion_Host\", \"Internal_DB\", 3.0)\ntg.add_edge(\"Internal_API\", \"Internal_DB\", 4.0)\n\ncost, path = tg.find_shortest_attack_path(\"Internet\", \"Internal_DB\")\nprint(f\"Optimal Exploit Path: {' -> '.join(path)} (Cost: {cost}h)\")",
