        "code": "import json, base64, hmac, hashlib\n\nclass UnifiedZeroTrustGateway:\n    def __init__(self, jwt_secret, allowed_subnets):\n        self.jwt_secret = jwt_secret\n        self.allowed_subnets = allowed_subnets\n        self.permissions_db = {\n            (\"user:alice\", \"read\", \"resource:finances\"): True\n        }\n\n    def process_request(self, token, client_ip, action, target_resource, raw_user_input):\n        # 1. JWT validation\n        parts = token.split(\".\")\n        if len(parts) != 3:\n            raise PermissionError(\"GATEWAY_AUTH_FAIL: Malformed token\")\n        h, p, s = parts\n        expected_sig = base64.urlsafe_b64encode(hmac.new(self.jwt_secret, f\"{h}.{p}\".encode(), hashlib.sha256).digest()).decode().rstrip('=')\n        if not hmac.compare_digest(s, expected_sig):\n            raise PermissionError(\"GATEWAY_AUTH_FAIL: Invalid token signature\")\n        payload = json.loads(base64.urlsafe_b64decode(p + \"==\").decode())\n        user_id = payload.get(\"sub\")\n\n        # 2. ABAC Context\n        if not any(client_ip.startswith(sub) for sub in self.allowed_subnets):\n            raise PermissionError(\"GATEWAY_ABAC_DENIED: Client subnet unauthorized\")\n\n        # 3. ReBAC check\n        if not self.permissions_db.get((user_id, action, target_resource)):\n            raise PermissionError(\"GATEWAY_REBAC_DENIED: User lacks required relation\")\n\n        # 4. Injection check\n        if any(bad in raw_user_input for bad in [\"--\", \"UNION\", \"$gt\"]):\n            raise PermissionError(\"GATEWAY_INJECTION_BLOCKED: Malicious query syntax\")\n\n        return {\"status\": \"AUTHORIZED\", \"user\": user_id, \"resource\": target_resource}\n\nsecret = b\"gateway_master_secret_key_32_bytes\"\nh = base64.urlsafe_b64encode(json.dumps({\"alg\": \"HS256\"}).encode()).decode().rstrip('=')\np = base64.urlsafe_b64encode(json.dumps({\"sub\": \"user:alice\"}).encode()).decode().rstrip('=')\ns = base64.urlsafe_b64encode(hmac.new(secret, f\"{h}.{p}\".encode(), hashlib.sha256).digest()).decode().rstrip('=')\ntok = f\"{h}.{p}.{s}\"\n\ngw = UnifiedZeroTrustGateway(secret, [\"10.0.\"])\nres = gw.process_request(tok, \"10.0.1.42\", \"read\", \"resource:finances\", \"account_98234\")\nprint(f\"Gateway Decision: {res['status']} | User: {res['user']} | Resource: {res['resource']}\")",
